const RECENT_VIEWS_MAX=30;const RECENT_PRODUCTS_KEY="skiri_recent_products";const RECENT_STORES_KEY="skiri_recent_stores";function readRecent(key){try{const list=JSON.parse(localStorage.getItem(key)||"[]");return Array.isArray(list)?list.filter(e=>e&&typeof e==="object"&&e.id):[]}catch(e){return[]}}function writeRecent(key,list){try{localStorage.setItem(key,JSON.stringify(list.slice(0,RECENT_VIEWS_MAX)))}catch(e){}}const clip=(s,n)=>String(s==null?"":s).slice(0,n);function pushRecent(key,entry){const list=readRecent(key).filter(e=>e.id!==entry.id);list.unshift(entry);writeRecent(key,list)}function recordRecentProduct(product,storeSlug,res){if(!product||!product.productId||!storeSlug)return;res=res||{};pushRecent(RECENT_PRODUCTS_KEY,{id:clip(product.productId,80),storeSlug:clip(storeSlug,120),name:clip(product.name,200),imageUrl:clip(product.imageUrl,1e3),listingType:clip(product.listingType,20),storeName:clip(res.storeName,200),island:clip(res.storeIsland,100),village:clip(res.storeVillage,100),at:Date.now()})}function recordRecentStore(storeSlug,res){if(!storeSlug||!res)return;pushRecent(RECENT_STORES_KEY,{id:clip(storeSlug,120),name:clip(res.storeName,200),logoUrl:clip(res.storeLogoUrl,1e3),island:clip(res.storeIsland,100),village:clip(res.storeVillage,100),at:Date.now()})}function getRecentProducts(){return readRecent(RECENT_PRODUCTS_KEY)}function getRecentStores(){return readRecent(RECENT_STORES_KEY)}function clearRecentViews(){try{localStorage.removeItem(RECENT_PRODUCTS_KEY);localStorage.removeItem(RECENT_STORES_KEY)}catch(e){}}